# -*- coding: utf-8 -*-
"""YOUBIN SAMIUL single-file launcher for Render and Railway.

Extracts bundled modules next to this file, then runs app.py (match engine).
This launcher file is NEVER overwritten — engine lives in app.py.
"""
import base64
import importlib.util
import json
import os
from pathlib import Path
import runpy
import subprocess
import sys
import zlib

# Active login/online/match engine is based on ahare.zip/app.py.
# Runtime modules and dashboard assets are embedded; engine is app.py (not main.py).
BUNDLED_FILES = json.loads('{"dashboard_server.py":"","CguTeam_pb2.py":"eNpdjrEKAjEQRPt8xcD1V9hbaSsIcrUkl4QEk2zY7BH8e8WAnNbz5s1MOFGuWqKJKcoTnXWtjuGJIcHhJprlomUNqExCZvNoa3BZz2rC0lz7YGYrNjk78OV8HY0BQheLTvxo6FECKNn3wNfGW5GYXZuVZ8q7wXs1B8RcieXXq3anjn/RC+oSS08=","CguFF_pb2.py":"eNpdjrEKAjEQRPt8xcD1V9hbaSsIcrUkl4QEk2zY7BH8e8WAnNbz5s1MOFGuWqKJKcoTnXWtjuGJIcHhJprlomUNqExCZvNoa3BZz2rC0lz7YGYrNjk78OV8HY0BQheLTvxo6FECKNn3wNfGW5GYXZuVZ8q7wXs1B8RcieXXq3anjn/RC+oSS08=","thunderFF_pb2.py":"","StartMatch_pb2.py":"","message_ids.py":"","RbcFF_pb2.py":"","RbcTeam_pb2.py":"","app.py":"","templates/index.html":"","templates/auth.html":"","templates/landing.html":"","templates/profile-banner.mp4":""}')

# import name -> pip package name
REQUIRED = {
    "aiohttp": "aiohttp",
    "httpx": "httpx",
    "requests": "requests",
    "Crypto": "pycryptodome",
    "google.protobuf": "protobuf",
    "google_play_scraper": "google-play-scraper",
    "protobuf_decoder": "protobuf-decoder",
    "jwt": "PyJWT",
}


def _has(module: str) -> bool:
    try:
        return importlib.util.find_spec(module) is not None
    except (ImportError, ValueError):
        return False


def _is_termux() -> bool:
    return "com.termux" in os.environ.get("PREFIX", "") or os.path.isdir("/data/data/com.termux")


def ensure_dependencies() -> None:
    missing = [pip for mod, pip in REQUIRED.items() if not _has(mod)]
    if not missing:
        return
    termux = _is_termux()
    print("\n[setup] Missing Python packages: " + ", ".join(missing))
    auto_flag = os.environ.get("AUTO_INSTALL")
    if auto_flag != "0":
        print("[setup] Installing them now (internet needed, this runs only once)...")
        env = dict(os.environ)
        if termux:
            env.update(MULTIDICT_NO_EXTENSIONS="1", YARL_NO_EXTENSIONS="1", FROZENLIST_NO_EXTENSIONS="1")
        code = subprocess.call([sys.executable, "-m", "pip", "install", *missing], env=env)
        importlib.invalidate_caches()
        missing = [pip for mod, pip in REQUIRED.items() if not _has(mod)]
        if code == 0 and not missing:
            print("[setup] Done. Starting the app...\n")
            return
        print("[setup] Automatic install did not finish. Still missing: " + ", ".join(missing or ["(see pip errors above)"]))
    print("\nInstall them manually, then run the app again:\n")
    if termux:
        print("  pkg update -y && pkg install -y python clang libffi openssl binutils")
        print("  MULTIDICT_NO_EXTENSIONS=1 YARL_NO_EXTENSIONS=1 FROZENLIST_NO_EXTENSIONS=1 pip install aiohttp")
        print("  pip install " + " ".join(p for p in REQUIRED.values() if p != "aiohttp"))
    else:
        print("  pip install " + " ".join(REQUIRED.values()))
    print("\nNote: engine is extracted as app.py; this launcher (main.py) is never overwritten.\n")
    sys.exit(1)


def resolve_app_dir() -> Path:
    root = Path(__file__).resolve().parent
    if os.access(root, os.W_OK):
        return root
    fallback = Path.home() / ".youbin_samiul_app"
    fallback.mkdir(parents=True, exist_ok=True)
    print(f"[setup] {root} is not writable. Using {fallback} instead.")
    return fallback


ROOT = resolve_app_dir()
LAUNCHER_PATH = Path(__file__).resolve()

for relative_path, encoded_content in BUNDLED_FILES.items():
    # Never extract over this launcher file
    if relative_path in ("main.py", "__main__.py"):
        print(f"[setup] Skip embedded path that would overwrite launcher: {relative_path}")
        continue
    destination = (ROOT / relative_path).resolve()
    if destination == LAUNCHER_PATH:
        print(f"[setup] Skip extract onto launcher: {relative_path}")
        continue
    if destination != ROOT and ROOT not in destination.parents:
        raise RuntimeError(f"Invalid embedded application path: {relative_path}")
    destination.parent.mkdir(parents=True, exist_ok=True)
    decoded = zlib.decompress(base64.b64decode(encoded_content))
    temporary = destination.with_name(destination.name + f".tmp-{os.getpid()}")
    try:
        temporary.write_bytes(decoded)
        os.replace(temporary, destination)
    finally:
        try:
            if temporary.exists():
                temporary.unlink()
        except OSError:
            pass

print(f"[setup] Extracted embedded files to: {ROOT}")
print("[setup] Engine file: app.py (launcher main.py is kept intact)")
ensure_dependencies()
os.chdir(ROOT)
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

engine_path = ROOT / "app.py"
if not engine_path.is_file():
    print("[setup] ERROR: app.py missing after extract")
    sys.exit(1)

runpy.run_path(str(engine_path), run_name="__main__")
